57	func run(args []string, stdout, stderr io.Writer) int {
58		if len(args) == 0 {
59			fmt.Fprint(stderr, usageText)
60			return 2
61		}
62		var opts options
63		// 手工解析位于子命令前后的全局参数，flag 包不支持子命令前的散落标志。
64		rest := args
65		for len(rest) > 0 && strings.HasPrefix(rest[0], "-") {
66			a := rest[0]
67			switch {
68			case a == "-f" || a == "--file":
69				if len(rest) < 2 {
70					fmt.Fprintf(stderr, "%s 需要一个值\n", a)
71					return 2
72				}
73				opts.file = rest[1]
74				rest = rest[2:]
75			case strings.HasPrefix(a, "--file="):
76				opts.file = strings.TrimPrefix(a, "--file=")
77				rest = rest[1:]
78			case strings.HasPrefix(a, "-f") && len(a) > 2:
79				opts.file = a[2:]
80				rest = rest[1:]
81			case a == "--json":
82				opts.asJSON = true
83				rest = rest[1:]
84			default:
85				fmt.Fprintf(stderr, "未知全局参数 %s\n\n%s", a, usageText)
86				return 2
87			}
88		}
89		if opts.file == "" {
90			opts.file = "ledger.json"
91		}
92		if len(rest) == 0 {
93			fmt.Fprint(stderr, usageText)
94			return 2
95		}
96		cmd, cmdArgs := rest[0], rest[1:]
97		if cmd == "help" || cmd == "-h" || cmd == "--help" {
98			fmt.Fprint(stdout, usageText)
99			return 0
100		}
101	
102		l, err := calibrate.Open(opts.file)
103		if err != nil {
104			fmt.Fprintln(stderr, "打开台账失败：", err)
105			return 2
106		}
107	
108		switch cmd {
109		case "register":
110			return cmdRegister(l, cmdArgs, opts, stdout, stderr)
111		case "status":
112			return cmdStatus(l, cmdArgs, opts, stdout, stderr)
113		case "cert":
114			return cmdCert(l, cmdArgs, opts, stdout, stderr)
115		case "use":
116			return cmdUse(l, cmdArgs, opts, stdout, stderr)
117		case "review":
118			return cmdReview(l, cmdArgs, opts, stdout, stderr)
119		case "list":
120			return cmdList(l, cmdArgs, opts, stdout, stderr)
121		default:
122			fmt.Fprintf(stderr, "未知子命令 %q\n\n%s", cmd, usageText)
123			return 2
124		}
125	}
