127	// newFlagSet 构造子命令自己的标志集，全局参数仍可写在子命令之后。
128	func newFlagSet(name string, opts *options) *flag.FlagSet {
129		fs := flag.NewFlagSet(name, flag.ContinueOnError)
130		fs.SetOutput(io.Discard)
131		fs.StringVar(&opts.file, "f", opts.file, "台账文件路径")
132		fs.StringVar(&opts.file, "file", opts.file, "台账文件路径")
133		fs.BoolVar(&opts.asJSON, "json", opts.asJSON, "以 JSON 输出")
134		return fs
135	}
136	
137	func parseFloat(stderr io.Writer, raw, field string) (float64, bool) {
138		v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
139		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) {
140			fmt.Fprintf(stderr, "%s 必须是有限数字\n", field)
141			return 0, false
142		}
143		return v, true
144	}
145	
146	func emit(opts options, stdout, stderr io.Writer, human string, v any) int {
147		if opts.asJSON {
148			raw, err := json.MarshalIndent(v, "", "  ")
149			if err != nil {
150				fmt.Fprintln(stderr, "输出 JSON 失败：", err)
151				return 2
152			}
153			fmt.Fprintln(stdout, string(raw))
154			return 0
155		}
156		fmt.Fprint(stdout, human)
157		return 0
158	}
159	
160	// failBusiness 处理业务拒绝：退出码 1，原记录未被改动。
161	func failBusiness(opts options, stdout, stderr io.Writer, err error, rejected any) int {
162		if opts.asJSON {
163			raw, _ := json.MarshalIndent(rejected, "", "  ")
164			fmt.Fprintln(stdout, string(raw))
165		}
166		fmt.Fprintln(stderr, "已拒绝：", err)
167		return 1
168	}
169	
170	func failIO(stderr io.Writer, err error) int {
171		fmt.Fprintln(stderr, "操作失败：", err)
172		return 2
173	}
174	
175	func cmdRegister(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
176		fs := newFlagSet("register", &opts)
177		id := fs.String("id", "", "器具唯一编号")
178		name := fs.String("name", "", "器具名称")
179		allowed := fs.String("allowed", "", "允许的绝对误差（不小于零的有限数）")
180		if err := fs.Parse(args); err != nil {
181			fmt.Fprintln(stderr, "register 参数错误：", err)
182			return 2
183		}
184		if *id == "" || *name == "" || *allowed == "" {
185			fmt.Fprintln(stderr, "register 必须提供 --id、--name、--allowed")
186			return 2
187		}
188		allowedErr, ok := parseFloat(stderr, *allowed, "允许的绝对误差")
189		if !ok {
190			return 2
191		}
192		inst, err := l.Register(calibrate.RegisterInput{
193			ID: *id, Name: *name, AllowedError: allowedErr,
194		})
195		if err != nil {
196			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
197				return failBusiness(opts, stdout, stderr, err,
198					map[string]any{"accepted": false, "error": err.Error()})
199			}
200			return failIO(stderr, err)
201		}
202		human := fmt.Sprintf("已登记器具 %s（%s），允许绝对误差 %g，状态：%s\n",
203			inst.ID, inst.Name, inst.AllowedError, inst.Status)
204		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "instrument": inst})
205	}
206	
207	func cmdStatus(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
208		fs := newFlagSet("status", &opts)
209		id := fs.String("id", "", "器具编号")
210		status := fs.String("status", "", "在用|停用|待校准")
211		if err := fs.Parse(args); err != nil {
212			fmt.Fprintln(stderr, "status 参数错误：", err)
213			return 2
214		}
215		if *id == "" || *status == "" {
216			fmt.Fprintln(stderr, "status 必须提供 --id、--status")
217			return 2
218		}
219		st, err := calibrate.ParseStatus(*status)
220		if err != nil {
221			fmt.Fprintln(stderr, err)
222			return 2
223		}
224		if err := l.SetStatus(*id, st); err != nil {
225			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
226				return failBusiness(opts, stdout, stderr, err,
227					map[string]any{"accepted": false, "error": err.Error()})
228			}
229			return failIO(stderr, err)
230		}
231		human := fmt.Sprintf("器具 %s 已切换为%s\n", *id, st)
232		return emit(opts, stdout, stderr, human,
233			map[string]any{"accepted": true, "id": *id, "status": st})
234	}
235	
236	func cmdCert(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
237		fs := newFlagSet("cert", &opts)
238		instrument := fs.String("instrument", "", "器具编号")
239		number := fs.String("number", "", "证书编号（全台账唯一）")
240		calDate := fs.String("cal-date", "", "校准日期 YYYY-MM-DD")
241		expiry := fs.String("expiry", "", "有效期截止日 YYYY-MM-DD")
242		method := fs.String("method", "", "校准方法")
243		measured := fs.String("error", "", "测得误差（有限数）")
244		summary := fs.String("summary", "", "证书摘要")
245		if err := fs.Parse(args); err != nil {
246			fmt.Fprintln(stderr, "cert 参数错误：", err)
247			return 2
248		}
249		missing := []string{}
250		for k, v := range map[string]string{
251			"--instrument": *instrument, "--number": *number, "--cal-date": *calDate,
252			"--expiry": *expiry, "--method": *method, "--error": *measured, "--summary": *summary,
253		} {
254			if strings.TrimSpace(v) == "" {
255				missing = append(missing, k)
256			}
257		}
258		if len(missing) > 0 {
259			fmt.Fprintln(stderr, "cert 缺少必填参数：", strings.Join(missing, "、"))
260			return 2
261		}
262		measuredErr, ok := parseFloat(stderr, *measured, "测得误差")
263		if !ok {
264			return 2
265		}
266		cert, duplicate, err := l.AddCertificate(calibrate.CertificateInput{
267			InstrumentID: *instrument,
268			Number:       *number,
269			CalDate:      *calDate,
270			Expiry:       *expiry,
271			Method:       *method,
272			Error:        measuredErr,
273			Summary:      *summary,
274		})
275		if err != nil {
276			if calibrate.IsValidation(err) || calibrate.IsConflict(err) || errors.Is(err, calibrate.ErrNotFound) {
277				return failBusiness(opts, stdout, stderr, err,
278					map[string]any{"accepted": false, "conflict": calibrate.IsConflict(err), "error": err.Error()})
279			}
280			return failIO(stderr, err)
281		}
282		note := "已录入新证书"
283		if duplicate {
284			note = "同号证书且内容一致，返回原证书，未增加历史记录"
285		}
286		verdict := "合格"
287		if math.Abs(cert.Error) > allowedErrorOf(l, cert.InstrumentID) {
288			verdict = "超差"
289		}
290		human := fmt.Sprintf("%s：%s（器具 %s，校准日期 %s，截止日 %s，测得误差 %g，判定：%s）\n",
291			note, cert.Number, cert.InstrumentID, cert.CalDate, cert.Expiry, cert.Error, verdict)
292		return emit(opts, stdout, stderr, human,
293			map[string]any{"accepted": true, "duplicate": duplicate, "verdict": verdict, "certificate": cert})
294	}
295	
296	func allowedErrorOf(l *calibrate.Ledger, id string) float64 {
297		r, err := l.Review(id)
298		if err != nil {
299			return 0
300		}
301		return r.Instrument.AllowedError
302	}
303	
304	func cmdUse(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
305		fs := newFlagSet("use", &opts)
306		id := fs.String("id", "", "器具编号")
307		if err := fs.Parse(args); err != nil {
308			fmt.Fprintln(stderr, "use 参数错误：", err)
309			return 2
310		}
311		if strings.TrimSpace(*id) == "" {
312			fmt.Fprintln(stderr, "use 必须提供 --id")
313			return 2
314		}
315		d, err := l.RequestUse(*id)
316		if err != nil {
317			if errors.Is(err, calibrate.ErrNotFound) || calibrate.IsValidation(err) {
318				return failBusiness(opts, stdout, stderr, err,
319					map[string]any{"accepted": false, "recorded": false, "error": err.Error()})
320			}
321			return failIO(stderr, err)
322		}
323		if !d.Allowed {
324			var sb strings.Builder
325			sb.WriteString(fmt.Sprintf("拒绝使用器具 %s，已记录本次拒绝及原因：\n", *id))
326			for _, r := range d.Reasons {
327				sb.WriteString("  - " + r + "\n")
328			}
329			if opts.asJSON {
330				raw, _ := json.MarshalIndent(map[string]any{
331					"allowed": false, "recorded": true, "decision": d,
332				}, "", "  ")
333				fmt.Fprintln(stdout, string(raw))
334			}
335			fmt.Fprint(stderr, sb.String())
336			return 1
337		}
338		human := fmt.Sprintf("允许使用器具 %s，已记录本次申请。\n", *id)
339		return emit(opts, stdout, stderr, human,
340			map[string]any{"allowed": true, "recorded": true, "decision": d})
341	}
342	
343	func cmdReview(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
344		fs := newFlagSet("review", &opts)
345		id := fs.String("id", "", "器具编号")
346		if err := fs.Parse(args); err != nil {
347			fmt.Fprintln(stderr, "review 参数错误：", err)
348			return 2
349		}
350		if strings.TrimSpace(*id) == "" {
351			fmt.Fprintln(stderr, "review 必须提供 --id")
352			return 2
353		}
354		r, err := l.Review(*id)
355		if err != nil {
356			if errors.Is(err, calibrate.ErrNotFound) {
357				return failBusiness(opts, stdout, stderr, err,
358					map[string]any{"found": false, "error": err.Error()})
359			}
360			return failIO(stderr, err)
361		}
362		var sb strings.Builder
363		fmt.Fprintf(&sb, "器具 %s（%s）\n", r.Instrument.ID, r.Instrument.Name)
364		fmt.Fprintf(&sb, "  允许绝对误差：%g；当前状态：%s\n", r.Instrument.AllowedError, r.Instrument.Status)
365		if r.CanUse {
366			sb.WriteString("  当前能否使用：可以\n")
367		} else {
368			sb.WriteString("  当前能否使用：不可以，原因：\n")
369			for _, reason := range r.Reasons {
370				sb.WriteString("    - " + reason + "\n")
371			}
372		}
373		if r.Latest == nil {
374			sb.WriteString("  最近证书：无\n")
375		} else {
376			fmt.Fprintf(&sb, "  最近证书：%s（校准日期 %s，截止日 %s，判定：%s，%s）\n",
377				r.Latest.Number, r.Latest.CalDate, r.Latest.Expiry,
378				verdictText(r.Latest.Pass), expiryText(r.Latest.Expired))
379		}
380		if len(r.History) == 0 {
381			sb.WriteString("  历史证书：无\n")
382		} else {
383			sb.WriteString("  历史证书（按校准日期由近到远）：\n")
384			for _, c := range r.History {
385				fmt.Fprintf(&sb, "    - %s %s 截止 %s 误差 %g %s %s（%s）\n",
386					c.Number, c.CalDate, c.Expiry, c.Error,
387					verdictText(c.Pass), expiryText(c.Expired), c.Method)
388			}
389		}
390		if len(r.Rejections) == 0 {
391			sb.WriteString("  被拒绝的使用记录：无\n")
392		} else {
393			sb.WriteString("  被拒绝的使用记录（原因为申请当时冻结）：\n")
394			for _, u := range r.Rejections {
395				sb.WriteString("    - " + u.RequestedAt + "\n")
396				for _, reason := range u.Reasons {
397					sb.WriteString("        - " + reason + "\n")
398				}
399			}
400		}
401		return emit(opts, stdout, stderr, sb.String(), r)
402	}
403	
404	func verdictText(pass bool) string {
405		if pass {
406			return "合格"
407		}
408		return "超差"
409	}
410	
411	func expiryText(expired bool) string {
412		if expired {
413			return "已到期"
414		}
415		return "未到期"
416	}
417	
418	func cmdList(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
419		fs := newFlagSet("list", &opts)
420		if err := fs.Parse(args); err != nil {
421			fmt.Fprintln(stderr, "list 参数错误：", err)
422			return 2
423		}
424		instruments := l.Instruments()
425		var sb strings.Builder
426		if len(instruments) == 0 {
427			sb.WriteString("台账中还没有器具。\n")
428		}
429		for _, in := range instruments {
430			fmt.Fprintf(&sb, "%s\t%s\t允许误差 %g\t%s\n", in.ID, in.Name, in.AllowedError, in.Status)
431		}
432		return emit(opts, stdout, stderr, sb.String(),
433			map[string]any{"instruments": instruments, "count": len(instruments)})
434	}
