```go
// TodoPlan 是待办计划视图，附带器具信息与按当前日期判定的到期标记。
type TodoPlan struct {
	Plan
	InstrumentName   string `json:"instrument_name"`
	InstrumentStatus Status `json:"instrument_status"`
	DueLabel         string `json:"due_label"`
}

// TodoPlans 返回未结束计划（可按器具编号筛选），按计划日期从早到晚、
// 同日按器具编号排列。到期标记在每次查询时按本机日期重新判断，查询不留痕。
func (l *Ledger) TodoPlans(instrumentID string) ([]TodoPlan, error) {
	if strings.TrimSpace(instrumentID) != "" && l.findInstrument(strings.TrimSpace(instrumentID)) == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", strings.TrimSpace(instrumentID), ErrNotFound)
	}
	todayText := l.now().Format(DateLayout)
	var out []TodoPlan
	for i := range l.data.Plans {
		p := &l.data.Plans[i]
		if p.Status != PlanActive {
			continue
		}
		if instrumentID != "" && p.InstrumentID != instrumentID {
			continue
		}
		inst := l.findInstrument(p.InstrumentID)
		item := TodoPlan{Plan: *p}
		if inst != nil {
			item.InstrumentName = inst.Name
			item.InstrumentStatus = inst.Status
		}
		switch {
		case p.PlanDate == todayText:
			item.DueLabel = "今天需校准"
		case p.PlanDate < todayText:
			item.DueLabel = "逾期"
		default:
			item.DueLabel = "未到计划日"
		}
		out = append(out, item)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].PlanDate != out[j].PlanDate {
			return out[i].PlanDate < out[j].PlanDate
		}
		return out[i].InstrumentID < out[j].InstrumentID
	})
	return out, nil
}
```

