const planUsageText = `校准计划用法：
  ledger plan create     --instrument 器具编号 --number 计划编号 \
                         --date YYYY-MM-DD --description 说明
  ledger plan reschedule --number 计划编号 --date YYYY-MM-DD --reason 原因
